NUEVOS = {'scripts/bronze_key/clave_bronce.py': '#!/usr/bin/python3 -I\n# clave_bronce.py — [CLAVE-BRONCE-D326] DAY326, F2d de DEBT-FALCO-RUIDO-ADMIN-001 (PR2b de DEBT-ETCD-HA-TLS-RAFT-001).\n# Se ejecuta EN EL DEFENDER con sudo (la clave TLS del conversor es 0600 root). Imprime en stdout la clave HMAC ACTIVA\n# (64 hex) de un componente, la que mitre/ctu/custom-start pasan al bronze-to-gold-converter y la que comparan las\n# huellas de d317_reinicio_defender.sh. La pide por mTLS con la identidad del conversor (OU=CN=bronze-to-gold-converter;\n# la regla de /secrets/valid/{c} del etcd-server le deja leerla) a la primera dirección del bloque etcd del JSON del\n# ml-detector: así el conversor y el ml-detector hablan con el mismo etcd-server y no pueden quedar con claves distintas.\n# Sustituye a clave_bronce_ml_detector.sh y al curl de d317_reinicio_defender.sh (decisión de Alonso DAY326: sin curl;\n# Falco conoce a esta orden, no a un curl). Python estándar, sin dependencias.\n#   sudo python3 -I /vagrant/scripts/bronze_key/clave_bronce.py [--json RUTA] [--pki DIR] COMPONENTE\n# Del JSON (el JSON es la ley): etcd.endpoints[0] (https://host:puerto, sin defecto), etcd.ca_file (ruta absoluta, sin\n# defecto) y etcd.connection_timeout_ms ([100, 60000], defecto 5000 con aviso: los mismos que etcd_client). Cada valor\n# efectivo, y de dónde sale, a stderr; por stdout solo la clave.\n# Salida: 0 bien; 1 error (red, TLS, HTTP, respuesta); 2 uso o configuración. Errores a stderr.\nimport argparse\nimport http.client\nimport json\nimport re\nimport ssl\nimport sys\nimport urllib.parse\n\nTAG = "[CLAVE-BRONCE]"\nJSON_DEFECTO = "/etc/ml-defender/ml-detector/ml_detector_config.json"\nPKI_DEFECTO = "/etc/argus-pki"\nID = "bronze-to-gold-converter"\n# Los de etcd_client::leer_bloque_etcd() (el _doc del bloque etcd de ml_detector_config.json)\nTIMEOUT_DEFECTO_MS, TIMEOUT_MIN_MS, TIMEOUT_MAX_MS = 5000, 100, 60000\nMAX_RESPUESTA = 1 << 20\nSALIDA_OK, SALIDA_ERROR, SALIDA_USO = 0, 1, 2\n\n\nclass Fallo(Exception):\n    def __init__(self, mensaje, codigo=SALIDA_ERROR):\n        super().__init__(mensaje)\n        self.codigo = codigo\n\n\ndef leer_bloque(ruta):\n    """(host, puerto, ca_file, timeout_ms, líneas de log) del bloque etcd de un JSON de componente."""\n    try:\n        with open(ruta, encoding="utf-8") as f:\n            j = json.load(f)\n    except (OSError, ValueError) as e:\n        raise Fallo(f"{TAG} no se puede leer {ruta}: {e}", SALIDA_USO) from None\n    e = j.get("etcd") if isinstance(j, dict) else None\n    if not isinstance(e, dict):\n        raise Fallo(f"{TAG} {ruta} sin bloque etcd", SALIDA_USO)\n    eps = e.get("endpoints")\n    ep = eps[0] if isinstance(eps, list) and eps else None\n    if not isinstance(ep, str):\n        raise Fallo(f"{TAG} {ruta}: etcd.endpoints[0] ausente o mal formado (https://host:puerto)", SALIDA_USO)\n    u = urllib.parse.urlsplit(ep)\n    try:\n        puerto = u.port\n    except ValueError:\n        puerto = None\n    if u.scheme != "https" or not u.hostname or puerto is None or u.path not in ("", "/") or u.query or u.fragment:\n        raise Fallo(f"{TAG} {ruta}: etcd.endpoints[0]=\'{ep[:80]}\' no es https://host:puerto", SALIDA_USO)\n    ca = e.get("ca_file")\n    if not isinstance(ca, str) or not ca.startswith("/"):\n        raise Fallo(f"{TAG} {ruta}: etcd.ca_file ausente o mal formado (ruta absoluta)", SALIDA_USO)\n    log = [f"[CONFIG] etcd.endpoints[0]={ep} (JSON)", f"[CONFIG] etcd.ca_file={ca} (JSON)"]\n    t = e.get("connection_timeout_ms")\n    if type(t) is int and TIMEOUT_MIN_MS <= t <= TIMEOUT_MAX_MS:\n        log.append(f"[CONFIG] etcd.connection_timeout_ms={t} (JSON)")\n    else:\n        porque = "ausente" if t is None else "mal formado"\n        log.append(f"[CONFIG-DEFAULT] etcd.connection_timeout_ms={TIMEOUT_DEFECTO_MS} (DEFECTO: {porque}; entero en "\n                   f"[{TIMEOUT_MIN_MS}, {TIMEOUT_MAX_MS}] ms)")\n        t = TIMEOUT_DEFECTO_MS\n    return u.hostname, puerto, ca, t, log\n\n\ndef clave_activa(datos):\n    """La única clave activa (64 hex en minúsculas) de una respuesta de /secrets/valid/{c}."""\n    try:\n        d = json.loads(datos.decode("utf-8"))\n    except (UnicodeDecodeError, ValueError):\n        raise Fallo(f"{TAG} la respuesta no es JSON") from None\n    ks = d.get("keys") if isinstance(d, dict) else None\n    if not isinstance(ks, list):\n        raise Fallo(f"{TAG} la respuesta no trae la lista keys")\n    activas = [k.get("key") for k in ks if isinstance(k, dict) and k.get("is_active") is True]\n    if len(activas) != 1:\n        raise Fallo(f"{TAG} se esperaba 1 clave activa y hay {len(activas)}")\n    if not isinstance(activas[0], str) or re.fullmatch(r"[0-9a-f]{64}", activas[0]) is None:\n        raise Fallo(f"{TAG} la clave activa no son 64 hex")\n    return activas[0]\n\n\ndef pedir(host, puerto, ca, cert, key, timeout_s, ruta):\n    """GET por HTTPS con certificado de cliente: (status, cuerpo)."""\n    c = None\n    try:\n        ctx = ssl.create_default_context(cafile=ca)\n        ctx.minimum_version = ssl.TLSVersion.TLSv1_2\n        ctx.load_cert_chain(cert, key)\n        c = http.client.HTTPSConnection(host, puerto, context=ctx, timeout=timeout_s)\n        c.request("GET", ruta)\n        r = c.getresponse()\n        return r.status, r.read(MAX_RESPUESTA + 1)\n    except (OSError, http.client.HTTPException, ssl.SSLError) as e:\n        raise Fallo(f"{TAG} GET https://{host}:{puerto}{ruta}: {str(e)[:200]} (¿etcd-server de control-1 arrancado?)") \\\n            from None\n    finally:\n        if c is not None:\n            c.close()\n\n\ndef main(argv=None, pedir=pedir):\n    ap = argparse.ArgumentParser(prog="clave_bronce.py", description="Clave HMAC activa de un componente (ver cabecera)")\n    ap.add_argument("--json", default=JSON_DEFECTO, help=f"JSON con el bloque etcd (defecto {JSON_DEFECTO})")\n    ap.add_argument("--pki", default=PKI_DEFECTO, help=f"directorio del certificado del conversor (defecto {PKI_DEFECTO})")\n    ap.add_argument("componente")\n    a = ap.parse_args(sys.argv[1:] if argv is None else argv)\n    try:\n        if re.fullmatch(r"[a-z0-9-]{1,64}", a.componente) is None:\n            raise Fallo(f"{TAG} componente \'{a.componente[:64]}\' mal formado ([a-z0-9-], de 1 a 64)", SALIDA_USO)\n        host, puerto, ca, t, log = leer_bloque(a.json)\n        for ln in log:\n            print(f"{TAG} {ln}", file=sys.stderr)\n        ruta = f"/secrets/valid/{a.componente}"\n        st, datos = pedir(host, puerto, ca, f"{a.pki}/{ID}.crt", f"{a.pki}/{ID}.key", t / 1000, ruta)\n        if st != 200:\n            raise Fallo(f"{TAG} GET https://{host}:{puerto}{ruta}: HTTP {st}")\n        if len(datos) > MAX_RESPUESTA:\n            raise Fallo(f"{TAG} respuesta de más de {MAX_RESPUESTA} bytes")\n        print(clave_activa(datos))\n        return SALIDA_OK\n    except Fallo as e:\n        print(str(e), file=sys.stderr)\n        return e.codigo\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'scripts/bronze_key/test_clave_bronce.py': '#!/usr/bin/python3 -I\n# test_clave_bronce.py — [CLAVE-BRONCE-D326] tests de clave_bronce.py con la biblioteca estándar (unittest), sin red: la\n# lectura del bloque etcd (el JSON es la ley), la respuesta de /secrets/valid/{c} y la orden entera con la petición\n# HTTPS simulada. La petición real la prueban mitre-start y lab-e2e-reinicio-etcd.\n#   python3 -I scripts/bronze_key/test_clave_bronce.py      (make test-clave-bronce, en el defender)\nimport contextlib\nimport importlib.util\nimport io\nimport json\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.dont_write_bytecode = True  # se ejecuta desde /vagrant: sin __pycache__ en el repo\nAQUI = os.path.dirname(os.path.abspath(__file__))\n_spec = importlib.util.spec_from_file_location("clave_bronce", os.path.join(AQUI, "clave_bronce.py"))\ncb = importlib.util.module_from_spec(_spec)\n_spec.loader.exec_module(cb)\n\nK1 = "a" * 64\nK2 = "0123456789abcdef" * 4\n\n\ndef bloque(**kw):\n    e = {"endpoints": ["https://192.168.100.20:2379"], "ca_file": "/etc/argus-pki/ca.crt",\n         "connection_timeout_ms": 5000}\n    e.update(kw)\n    return e\n\n\ndef json_tmp(obj):\n    d = tempfile.mkdtemp()\n    r = os.path.join(d, "c.json")\n    with open(r, "w", encoding="utf-8") as f:\n        f.write(obj if isinstance(obj, str) else json.dumps(obj))\n    return r\n\n\ndef resp(*claves):\n    return json.dumps({"keys": [{"key": k, "is_active": a} for k, a in claves]}).encode()\n\n\nclass Bloque(unittest.TestCase):\n    def test_lee_lo_del_json_y_lo_dice(self):\n        h, p, ca, t, log = cb.leer_bloque(json_tmp({"etcd": bloque(connection_timeout_ms=2500)}))\n        self.assertEqual((h, p, ca, t), ("192.168.100.20", 2379, "/etc/argus-pki/ca.crt", 2500))\n        self.assertIn("[CONFIG] etcd.connection_timeout_ms=2500 (JSON)", log)\n        self.assertIn("[CONFIG] etcd.endpoints[0]=https://192.168.100.20:2379 (JSON)", log)\n\n    def test_timeout_ausente_o_fuera_de_rango_va_al_defecto_con_aviso(self):\n        for v, porque in ((None, "ausente"), (99, "mal formado"), (60001, "mal formado"), ("5000", "mal formado"),\n                          (True, "mal formado")):\n            e = bloque()\n            if v is None:\n                del e["connection_timeout_ms"]\n            else:\n                e["connection_timeout_ms"] = v\n            *_, t, log = cb.leer_bloque(json_tmp({"etcd": e}))\n            self.assertEqual(t, 5000, v)\n            self.assertIn(f"[CONFIG-DEFAULT] etcd.connection_timeout_ms=5000 (DEFECTO: {porque}; entero en "\n                          "[100, 60000] ms)", log, v)\n\n    def test_endpoint_y_ca_sin_defecto(self):\n        malos = [{"etcd": bloque(endpoints=[])}, {"etcd": bloque(endpoints="https://x:1")},\n                 {"etcd": bloque(endpoints=["http://192.168.100.20:2379"])},\n                 {"etcd": bloque(endpoints=["https://192.168.100.20"])},\n                 {"etcd": bloque(endpoints=["https://192.168.100.20:99999"])},\n                 {"etcd": bloque(endpoints=["https://192.168.100.20:2379/otra"])},\n                 {"etcd": bloque(ca_file="relativa.crt")}, {"etcd": bloque(ca_file=None)}, {"otro": 1}, [1], "{"]\n        for m in malos:\n            with self.assertRaises(cb.Fallo, msg=m) as c:\n                cb.leer_bloque(json_tmp(m))\n            self.assertEqual(c.exception.codigo, cb.SALIDA_USO, m)\n\n\nclass Respuesta(unittest.TestCase):\n    def test_una_sola_activa(self):\n        self.assertEqual(cb.clave_activa(resp((K1, False), (K2, True))), K2)\n\n    def test_rechaza(self):\n        for datos, texto in ((resp((K1, True), (K2, True)), "hay 2"), (resp((K1, False)), "hay 0"),\n                             (resp(("A" * 64, True)), "64 hex"), (resp(("a" * 63, True)), "64 hex"),\n                             (json.dumps({"keys": [{"key": K1, "is_active": "true"}]}).encode(), "hay 0"),\n                             (b"no es json", "no es JSON"), (b\'{"otra": 1}\', "lista keys")):\n            with self.assertRaises(cb.Fallo, msg=datos) as c:\n                cb.clave_activa(datos)\n            self.assertIn(texto, str(c.exception))\n\n\nclass Orden(unittest.TestCase):\n    def correr(self, argv, status=200, cuerpo=None):\n        self.pedidos = []\n\n        def falsa(host, puerto, ca, cert, key, timeout_s, ruta):\n            self.pedidos.append((host, puerto, ca, cert, key, timeout_s, ruta))\n            return status, cuerpo if cuerpo is not None else resp((K2, True))\n        out, err = io.StringIO(), io.StringIO()\n        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):\n            rc = cb.main(argv, pedir=falsa)\n        return rc, out.getvalue(), err.getvalue()\n\n    def test_imprime_solo_la_clave_y_pide_con_la_identidad_del_conversor(self):\n        j = json_tmp({"etcd": bloque()})\n        rc, out, err = self.correr(["--json", j, "--pki", "/pki", "firewall-acl-agent"])\n        self.assertEqual((rc, out), (0, K2 + "\\n"))\n        self.assertEqual(self.pedidos, [("192.168.100.20", 2379, "/etc/argus-pki/ca.crt",\n                                         "/pki/bronze-to-gold-converter.crt", "/pki/bronze-to-gold-converter.key",\n                                         5.0, "/secrets/valid/firewall-acl-agent")])\n        self.assertIn("[CLAVE-BRONCE] [CONFIG] etcd.connection_timeout_ms=5000 (JSON)", err)\n\n    def test_errores_sin_clave_por_stdout(self):\n        j = json_tmp({"etcd": bloque()})\n        for argv, kw, rc_esperado in ((["--json", j, "ml-detector"], {"status": 403}, 1),\n                                      (["--json", j, "ml-detector"], {"cuerpo": b"x" * (cb.MAX_RESPUESTA + 1)}, 1),\n                                      (["--json", j, "ml-detector"], {"cuerpo": resp((K1, False))}, 1),\n                                      (["--json", j, "../etc"], {}, 2),\n                                      (["--json", json_tmp("{"), "ml-detector"], {}, 2)):\n            rc, out, err = self.correr(argv, **kw)\n            self.assertEqual((rc, out), (rc_esperado, ""), (argv, kw))\n            self.assertIn("[CLAVE-BRONCE]", err)\n\n    def test_pedir_real_sin_certificado_es_un_fallo_claro(self):\n        with self.assertRaises(cb.Fallo) as c:\n            cb.pedir("127.0.0.1", 9, "/no/existe/ca.crt", "/no/c.crt", "/no/c.key", 1.0, "/secrets/valid/x")\n        self.assertIn("GET https://127.0.0.1:9/secrets/valid/x", str(c.exception))\n\n\nif __name__ == "__main__":\n    unittest.main(verbosity=2)\n'}


def sha(b):
    return hashlib.sha256(b).hexdigest()


def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ("--check", "--apply"):
        print(f"{TAG} uso: python3 -I scripts/etcd_ha/d326_f2d_clave_bronce.py --check | --apply", file=sys.stderr)
        return 2
    if not (os.path.isfile("Vagrantfile") and os.path.isdir(".git")):
        print(f"{TAG} FALLA: ejecútalo desde la raíz del repo", file=sys.stderr)
        return 1
    nuevos, ya = {}, 0
    for p in sorted(FINAL):
        existe = os.path.exists(p)
        if existe and sha(open(p, "rb").read()) == FINAL[p]:
            print(f"{TAG} {p}: ya aplicado")
            ya += 1
            continue
        if p in NUEVOS:
            if existe:
                print(f"{TAG} FALLA: {p} ya existe y no es el esperado; nada escrito", file=sys.stderr)
                return 1
            r = NUEVOS[p].encode("utf-8")
            que = "nuevo"
        else:
            if not existe:
                print(f"{TAG} FALLA: falta {p}; nada escrito", file=sys.stderr)
                return 1
            b = open(p, "rb").read()
            if sha(b) != INICIO[p]:
                print(f"{TAG} FALLA: {p} sha256 {sha(b)} no es el de partida {INICIO[p]} ni el final; nada escrito",
                      file=sys.stderr)
                return 1
            s = b.decode("utf-8")
            for i, (a, n, veces) in enumerate(CAMBIOS[p]):
                c = s.count(a)
                if c != veces:
                    print(f"{TAG} FALLA: {p} ancla {i} aparece {c} veces (se exigen {veces}); nada escrito",
                          file=sys.stderr)
                    return 1
                s = s.replace(a, n)
            r = s.encode("utf-8")
            que = f"{len(CAMBIOS[p])} anclas con sus veces exactas"
        if sha(r) != FINAL[p]:
            print(f"{TAG} FALLA: {p} resultado {sha(r)} no es el esperado {FINAL[p]}; nada escrito", file=sys.stderr)
            return 1
        nuevos[p] = r
        print(f"{TAG} {p}: {que}; resultado {FINAL[p][:16]}")
    if sys.argv[1] == "--check":
        print(f"{TAG} CHECK OK: {len(nuevos)} por aplicar, {ya} ya aplicados")
        return 0
    for p, r in nuevos.items():
        modo = os.stat(p).st_mode if os.path.exists(p) else 0o100644
        tmp = p + ".d326dtmp"
        with open(tmp, "wb") as f:
            f.write(r)
        os.chmod(tmp, modo & 0o7777)
        os.replace(tmp, p)
    print(f"{TAG} APLICADO: {len(nuevos)} escritos, {ya} ya estaban. Siguiente: "
          "git rm scripts/bronze_key/clave_bronce_ml_detector.sh")
    return 0


if __name__ == "__main__":
    sys.exit(main())
